using System.Collections.Generic;
using System.Globalization;

namespace ScumMiniMap {
    public enum AppLanguage {
        English = 0,
        SpanishArgentina = 1,
        French = 2,
        German = 3,
        Dutch = 4,
        Russian = 5,
        Chinese = 6,
        Turkish = 7,
        Arabic = 8,
        Portuguese = 9,
        Korean = 10,
        Polish = 11,
        PortuguesePortugal = 12,
        Thai = 13,
        ChineseTraditional = 14,
        Japanese = 15,
        Czech = 16,
        Italian = 17,
        Ukrainian = 18
    }

    public static partial class Localization {
        public static event Action LanguageChanged;

        private static AppLanguage currentLanguage = AppLanguage.English;
        public static string[] LanguageDisplayNames {
            get { return new[]{"English","Español (Argentina)","Français","Deutsch","Nederlands","Русский","中文 (简体)","Türkçe","العربية","Português (Brasil)","한국어","Polski","Português (Portugal)","ไทย","中文（繁體）","日本語","Čeština","Italiano","Українська"}; }
        }
        public static AppLanguage LanguageAt(int index) {
            return index>=0 && index<LanguageDisplayNames.Length ? (AppLanguage)index : AppLanguage.English;
        }

        public static AppLanguage Current {
            get { return currentLanguage; }
            set {
                if (currentLanguage != value) {
                    currentLanguage = value;
                    Action handler = LanguageChanged;
                    if (handler != null) handler();
                }
            }
        }

        public static string CurrentCode {
            get {
                switch (currentLanguage) {
                    case AppLanguage.SpanishArgentina: return "es-AR";
                    case AppLanguage.French: return "fr";
                    case AppLanguage.German: return "de";
                    case AppLanguage.Dutch: return "nl";
                    case AppLanguage.Russian: return "ru";
                    case AppLanguage.Chinese: return "zh-CN";
                    case AppLanguage.Turkish: return "tr";
                    case AppLanguage.Arabic: return "ar";
                    case AppLanguage.Portuguese: return "pt-BR";
                    case AppLanguage.Korean: return "ko";
                    case AppLanguage.Polish: return "pl";
                    case AppLanguage.PortuguesePortugal: return "pt-PT";
                    case AppLanguage.Thai: return "th";
                    case AppLanguage.ChineseTraditional: return "zh-TW";
                    case AppLanguage.Japanese: return "ja";
                    case AppLanguage.Czech: return "cs";
                    case AppLanguage.Italian: return "it";
                    case AppLanguage.Ukrainian: return "uk";
                    default: return "en";
                }
            }
        }

        public static void SetLanguage(string code) {
            if (string.IsNullOrWhiteSpace(code)) return;
            string normalized = code.Trim().ToLowerInvariant();
            if (normalized.StartsWith("es")) {
                Current = AppLanguage.SpanishArgentina;
            } else if (normalized.StartsWith("fr")) {
                Current = AppLanguage.French;
            } else if (normalized.StartsWith("de")) {
                Current = AppLanguage.German;
            } else if (normalized.StartsWith("nl")) {
                Current = AppLanguage.Dutch;
            } else if (normalized.StartsWith("ru")) {
                Current = AppLanguage.Russian;
            } else if (normalized=="zh-tw" || normalized.StartsWith("zh-tw-") || normalized.StartsWith("zh-hant") || normalized=="zh-hk" || normalized=="zh-mo") {
                Current = AppLanguage.ChineseTraditional;
            } else if (normalized.StartsWith("zh")) {
                Current = AppLanguage.Chinese;
            } else if (normalized.StartsWith("tr")) {
                Current = AppLanguage.Turkish;
            } else if (normalized.StartsWith("ar")) {
                Current = AppLanguage.Arabic;
            } else if (normalized == "pt-pt" || normalized.StartsWith("pt-pt-")) {
                Current = AppLanguage.PortuguesePortugal;
            } else if (normalized.StartsWith("pt")) {
                Current = AppLanguage.Portuguese;
            } else if (normalized.StartsWith("ko")) {
                Current = AppLanguage.Korean;
            } else if (normalized.StartsWith("pl")) {
                Current = AppLanguage.Polish;
            } else if (normalized.StartsWith("th")) {
                Current = AppLanguage.Thai;
            } else if (normalized.StartsWith("ja")) {
                Current = AppLanguage.Japanese;
            } else if (normalized.StartsWith("cs")) {
                Current = AppLanguage.Czech;
            } else if (normalized.StartsWith("it")) {
                Current = AppLanguage.Italian;
            } else if (normalized.StartsWith("uk")) {
                Current = AppLanguage.Ukrainian;
            } else {
                Current = AppLanguage.English;
            }
        }

        public static void DetectSystemLanguage() {
            SetLanguage(CultureInfo.CurrentUICulture.Name);
        }

        public static string Get(string key) {
            if (string.IsNullOrEmpty(key)) return string.Empty;
            Dictionary<string, string> dict = null;
            switch (currentLanguage) {
                case AppLanguage.SpanishArgentina: dict = StringsEsAr; break;
                case AppLanguage.French: dict = StringsFr; break;
                case AppLanguage.German: dict = StringsDe; break;
                case AppLanguage.Dutch: dict = StringsNl; break;
                case AppLanguage.Russian: dict = StringsRu; break;
                case AppLanguage.Chinese: dict = StringsZh; break;
                case AppLanguage.Turkish: dict = StringsTr; break;
                case AppLanguage.Arabic: dict = StringsAr; break;
                case AppLanguage.Portuguese: dict = StringsPt; break;
                case AppLanguage.PortuguesePortugal: dict = StringsPtPt; break;
                case AppLanguage.Korean: dict = StringsKo; break;
                case AppLanguage.Polish: dict = StringsPl; break;
                case AppLanguage.Thai: dict = StringsTh; break;
                case AppLanguage.ChineseTraditional: dict = StringsZhTw; break;
                case AppLanguage.Japanese: dict = StringsJa; break;
                case AppLanguage.Czech: dict = StringsCs; break;
                case AppLanguage.Italian: dict = StringsIt; break;
                case AppLanguage.Ukrainian: dict = StringsUk; break;
                default: dict = StringsEn; break;
            }
            string value;
            if (dict != null && dict.TryGetValue(key, out value)) {
                return value;
            }
            if (StringsEn != null && StringsEn.TryGetValue(key, out value)) {
                return value;
            }
            return key;
        }

        public static string T(string key, params object[] args) {
            string text = Get(key);
            if (args == null || args.Length == 0) return text;
            try {
                return string.Format(CultureInfo.InvariantCulture, text, args);
            } catch {
                return text;
            }
        }

        public static string GetZoneName(string englishName) {
            if (string.IsNullOrEmpty(englishName)) return string.Empty;
            if ((currentLanguage==AppLanguage.French || currentLanguage==AppLanguage.Chinese ||
                 currentLanguage==AppLanguage.Turkish || currentLanguage==AppLanguage.Arabic ||
                 currentLanguage==AppLanguage.Portuguese || currentLanguage==AppLanguage.PortuguesePortugal ||
                 currentLanguage==AppLanguage.Thai || currentLanguage==AppLanguage.ChineseTraditional ||
                 currentLanguage==AppLanguage.Japanese || currentLanguage==AppLanguage.Czech ||
                 currentLanguage==AppLanguage.Italian || currentLanguage==AppLanguage.Ukrainian) &&
                ZoneNamesEsAr.ContainsKey(englishName))
                return TranslateMapObject(englishName,CurrentMapObjects,CurrentMapCategories);
            Dictionary<string,string> additionalZones = currentLanguage == AppLanguage.German ? GermanZoneNames.Value :
                currentLanguage == AppLanguage.Dutch ? DutchZoneNames.Value :
                currentLanguage == AppLanguage.Polish ? PolishZoneNames.Value : null;
            string additionalName;
            if (additionalZones != null && additionalZones.TryGetValue(englishName, out additionalName)) return additionalName;
            if (currentLanguage == AppLanguage.Russian) {
                string localized;
                if (ZoneNamesRu.TryGetValue(englishName, out localized)) return localized;
            }
            if (currentLanguage == AppLanguage.Korean) {
                string localized;
                if (ZoneNamesKo.TryGetValue(englishName, out localized)) return localized;
                if (englishName.StartsWith("Gas Station - ", StringComparison.OrdinalIgnoreCase)) {
                    string sub = englishName.Substring("Gas Station - ".Length);
                    string locSub;
                    return "주유소 - " + (ZoneNamesKo.TryGetValue(sub, out locSub) ? locSub : sub);
                }
            }
            if (currentLanguage == AppLanguage.SpanishArgentina) {
                string localized;
                if (ZoneNamesEsAr != null && ZoneNamesEsAr.TryGetValue(englishName, out localized)) {
                    return localized;
                }
                if (englishName.StartsWith("Gas Station - ", StringComparison.OrdinalIgnoreCase)) {
                    string sub = englishName.Substring("Gas Station - ".Length);
                    string locSub;
                    if (ZoneNamesEsAr != null && ZoneNamesEsAr.TryGetValue(sub, out locSub)) {
                        return "Estación de Servicio - " + locSub;
                    }
                    return "Estación de Servicio - " + sub;
                }
            }
            return englishName;
        }

        public static string GetSectionName(string section) {
            if (string.IsNullOrEmpty(section)) return string.Empty;
            Dictionary<string, string> dict = null;
            switch (currentLanguage) {
                case AppLanguage.SpanishArgentina: dict = SectionNamesEsAr; break;
                case AppLanguage.French: dict = SectionNamesFr; break;
                case AppLanguage.German: dict = SectionNamesDe; break;
                case AppLanguage.Dutch: dict = SectionNamesNl; break;
                case AppLanguage.Russian: dict = SectionNamesRu; break;
                case AppLanguage.Chinese: dict = SectionNamesZh; break;
                case AppLanguage.Turkish: dict = SectionNamesTr; break;
                case AppLanguage.Arabic: dict = SectionNamesAr; break;
                case AppLanguage.Portuguese: dict = SectionNamesPt; break;
                case AppLanguage.PortuguesePortugal: dict = SectionNamesPtPt; break;
                case AppLanguage.Korean: dict = SectionNamesKo; break;
                case AppLanguage.Polish: dict = SectionNamesPl; break;
                case AppLanguage.Thai: dict = SectionNamesTh; break;
                case AppLanguage.ChineseTraditional: dict = SectionNamesZhTw; break;
                case AppLanguage.Japanese: dict = SectionNamesJa; break;
                case AppLanguage.Czech: dict = SectionNamesCs; break;
                case AppLanguage.Italian: dict = SectionNamesIt; break;
                case AppLanguage.Ukrainian: dict = SectionNamesUk; break;
            }
            if (dict != null) {
                string loc;
                if (dict.TryGetValue(section, out loc)) return loc;
            }
            return section;
        }

        public static string GetCategoryName(string category) {
            if (string.IsNullOrEmpty(category)) return string.Empty;
            string objectName;
            if (TryGetMapObjectName(category, out objectName)) return objectName;
            Dictionary<string, string> dict = null;
            switch (currentLanguage) {
                case AppLanguage.SpanishArgentina: dict = CategoryNamesEsAr; break;
                case AppLanguage.French: dict = CategoryNamesFr; break;
                case AppLanguage.German: dict = CategoryNamesDe; break;
                case AppLanguage.Dutch: dict = CategoryNamesNl; break;
                case AppLanguage.Russian: dict = CategoryNamesRu; break;
                case AppLanguage.Chinese: dict = CategoryNamesZh; break;
                case AppLanguage.Turkish: dict = CategoryNamesTr; break;
                case AppLanguage.Arabic: dict = CategoryNamesAr; break;
                case AppLanguage.Portuguese: dict = CategoryNamesPt; break;
                case AppLanguage.PortuguesePortugal: dict = CategoryNamesPtPt; break;
                case AppLanguage.Korean: dict = CategoryNamesKo; break;
                case AppLanguage.Polish: dict = CategoryNamesPl; break;
                case AppLanguage.Thai: dict = CategoryNamesTh; break;
                case AppLanguage.ChineseTraditional: dict = CategoryNamesZhTw; break;
                case AppLanguage.Japanese: dict = CategoryNamesJa; break;
                case AppLanguage.Czech: dict = CategoryNamesCs; break;
                case AppLanguage.Italian: dict = CategoryNamesIt; break;
                case AppLanguage.Ukrainian: dict = CategoryNamesUk; break;
            }
            if (dict != null) {
                string loc;
                if (dict.TryGetValue(category, out loc)) return loc;
            }
            return category;
        }

        public static void SelfTest() {
            // Inspect the actual catalogues: Get() intentionally falls back to English.
            var catalogues=new[]{StringsEn,StringsEsAr,StringsFr,StringsDe,StringsNl,StringsRu,StringsZh,StringsTr,StringsAr,StringsPt,StringsKo,StringsPl,StringsPtPt,StringsTh,StringsZhTw,StringsJa,StringsCs,StringsIt,StringsUk};
            if(catalogues.Length!=Enum.GetValues(typeof(AppLanguage)).Length || LanguageDisplayNames.Length!=catalogues.Length)
                throw new Exception("Language selectors and catalogues differ.");
            for(int language=0;language<catalogues.Length;language++) {
                var catalogue=catalogues[language];
                if(catalogue.Count!=StringsEn.Count) throw new Exception("Localization key count differs: "+(AppLanguage)language);
                foreach(var entry in StringsEn) {
                    string translated;
                    if(!catalogue.TryGetValue(entry.Key,out translated) || string.IsNullOrWhiteSpace(translated))
                        throw new Exception("Missing translation: "+(AppLanguage)language+" / "+entry.Key);
                    var expected=FormatArguments(entry.Value);
                    if(!expected.SetEquals(FormatArguments(translated)))
                        throw new Exception("Translation placeholders differ: "+(AppLanguage)language+" / "+entry.Key);
                    // Also reject malformed composite-format strings.
                    string.Format(CultureInfo.InvariantCulture,translated,new object[16]);
                }
            }
            ValidateNameCatalogue(SectionNamesPt, SectionNamesKo, "Korean sections");
            ValidateNameCatalogue(CategoryNamesPt, CategoryNamesKo, "Korean categories");
            ValidateNameCatalogue(ZoneNamesEsAr, ZoneNamesKo, "Korean zones");
            ValidateNameCatalogue(ZoneNamesEsAr, ZoneNamesRu, "Russian zones");
            ValidateNameCatalogue(ZoneNamesEsAr, GermanZoneNames.Value, "German zones");
            ValidateNameCatalogue(ZoneNamesEsAr, DutchZoneNames.Value, "Dutch zones");
            ValidateNameCatalogue(ZoneNamesEsAr, PolishZoneNames.Value, "Polish zones");
            ValidateNameCatalogue(MapObjectsEsAr, MapObjectsDe, "German map objects");
            ValidateNameCatalogue(MapObjectsEsAr, MapObjectsNl, "Dutch map objects");
            ValidateNameCatalogue(MapObjectsEsAr, MapObjectsPl, "Polish map objects");
            ValidateNameCatalogue(SectionNamesPt, SectionNamesPl, "Polish sections");
            ValidateNameCatalogue(SectionNamesPt, SectionNamesPtPt, "European Portuguese sections");
            ValidateNameCatalogue(CategoryNamesPt, CategoryNamesPtPt, "European Portuguese categories");
            foreach (var objects in new[]{MapObjectsFr,MapObjectsZh,MapObjectsTr,MapObjectsAr,MapObjectsPt,MapObjectsPtPt,MapObjectsKo})
                ValidateNameCatalogue(MapObjectsEsAr, objects, "Expanded map objects");
            foreach(var names in new[]{SectionNamesTh,SectionNamesZhTw,SectionNamesJa,SectionNamesCs,SectionNamesIt,SectionNamesUk})
                ValidateNameCatalogue(SectionNamesPt,names,"Added language sections");
            foreach(var names in new[]{CategoryNamesTh,CategoryNamesZhTw,CategoryNamesJa,CategoryNamesCs,CategoryNamesIt,CategoryNamesUk})
                ValidateNameCatalogue(CategoryNamesPt,names,"Added language categories");
            foreach(var names in new[]{MapObjectsTh,MapObjectsZhTw,MapObjectsJa,MapObjectsCs,MapObjectsIt,MapObjectsUk})
                ValidateNameCatalogue(MapObjectsEsAr,names,"Added language map objects");
        }

        static void ValidateNameCatalogue(Dictionary<string,string> reference, Dictionary<string,string> translated, string name) {
            if (reference.Count != translated.Count) throw new Exception("Localization key count differs: " + name);
            foreach (string key in reference.Keys) {
                string value;
                if (!translated.TryGetValue(key, out value) || string.IsNullOrWhiteSpace(value))
                    throw new Exception("Missing translation: " + name + " / " + key);
            }
        }

        static HashSet<string> FormatArguments(string text) {
            var arguments=new HashSet<string>();
            foreach(System.Text.RegularExpressions.Match match in System.Text.RegularExpressions.Regex.Matches(text,@"\{(\d+)(?:[,}:])"))
                arguments.Add(match.Groups[1].Value);
            return arguments;
        }
