            { "SetupSharingVisibility", "Die Karten-Seitenleiste bietet pro Spieler Schalter für Live-Position, GPS-Ziel, gespeicherte Orte und Todesmarkierungen. Sie ändern nur deine Ansicht; die Freigabe läuft weiter." },
